package dev.DraGonFiirE.littleperformanceimprovements.client.render;
import com.mojang.blaze3d.vertex.*;import it.unimi.dsi.fastutil.longs.LongArrayList;import org.lwjgl.system.MemoryUtil;import team.creative.littletiles.client.render.mc.MeshDataExtender;
public class PolygonOutlineLines {
 public static MeshData write(ByteBufferBuilder owner,LongArrayList[] edges,long sx,long sy,long sz,int[] min,double scale){long yz=sy*sz;var runs=new LongArrayList[3];int segments=0;for(int axis=0;axis<3;axis++){var list=edges[axis];long[] keys=list.elements();for(int i=0;i<list.size();i++){long k=keys[i],x=k/yz,y=(k%yz)/sz,z=k%sz;keys[i]=axis==0?(y*sz+z)*sx+x:axis==1?(z*sx+x)*sy+y:k;}java.util.Arrays.sort(keys,0,list.size());var pairs=new LongArrayList();long len=axis==0?sx:axis==1?sy:sz;for(int i=0;i<list.size();){long start=keys[i++],end=start+1,line=start/len;while(i<list.size()&&keys[i]<=end&&keys[i]/len==line){end=Math.max(end,keys[i]+1);i++;}pairs.add(start);pairs.add(end);}runs[axis]=pairs;segments+=pairs.size()/2;}if(segments==0)return null;long ptr=owner.reserve(Math.multiplyExact(segments,32));for(int axis=0;axis<3;axis++){var pairs=runs[axis];for(int i=0;i<pairs.size();i+=2){long k=pairs.getLong(i),length=pairs.getLong(i+1)-k;long x,y,z;if(axis==0){x=k%sx;long line=k/sx;y=line/sz;z=line%sz;}else if(axis==1){y=k%sy;long line=k/sy;z=line/sx;x=line%sx;}else{x=k/yz;y=k%yz/sz;z=k%sz;}float px=(float)((x+min[0]-1)*scale),py=(float)((y+min[1]-1)*scale),pz=(float)((z+min[2]-1)*scale),d=(float)(length*scale);MemoryUtil.memPutFloat(ptr,px);MemoryUtil.memPutFloat(ptr+4,py);MemoryUtil.memPutFloat(ptr+8,pz);MemoryUtil.memPutInt(ptr+12,-1);MemoryUtil.memPutFloat(ptr+16,px+(axis==0?d:0));MemoryUtil.memPutFloat(ptr+20,py+(axis==1?d:0));MemoryUtil.memPutFloat(ptr+24,pz+(axis==2?d:0));MemoryUtil.memPutInt(ptr+28,-1);ptr+=32;}}var mesh=new MeshData(owner.build(),new MeshData.DrawState(DefaultVertexFormat.POSITION_COLOR,segments*2,segments*2,VertexFormat.Mode.DEBUG_LINES,VertexFormat.IndexType.least(segments*2)));((MeshDataExtender)(Object)mesh).keepAlive(true);return mesh;}
}
